import{_ as a,o as i,c as e,ak as r}from"./chunks/framework.DvrM7GBU.js";const c=JSON.parse('{"title":"素材实例化与地图物体关系解析","description":"","frontmatter":{},"headers":[],"relativePath":"教程资料/专题研究/素材实例化与地图物体关系解析.md","filePath":"教程资料/专题研究/素材实例化与地图物体关系解析.md","lastUpdated":1777893104000}'),h={name:"教程资料/专题研究/素材实例化与地图物体关系解析.md"};function t(n,l,o,d,p,s){return i(),e("div",null,[...l[0]||(l[0]=[r('<h1 id="素材实例化与地图物体关系解析" tabindex="-1">素材实例化与地图物体关系解析 <a class="header-anchor" href="#素材实例化与地图物体关系解析" aria-label="Permalink to “素材实例化与地图物体关系解析”">​</a></h1><p>本文基于官方教程截图中“为什么修改了素材属性，地图中无变化？”相关内容，整理创游世界中“素材”和“地图物体”的关系。</p><h2 id="_1-素材不等于地图中的物体" tabindex="-1">1. 素材不等于地图中的物体 <a class="header-anchor" href="#_1-素材不等于地图中的物体" aria-label="Permalink to “1. 素材不等于地图中的物体”">​</a></h2><p>教程截图给出的核心结论非常明确：</p><ul><li>地图中的是<strong>物体</strong></li><li>素材栏中的是<strong>素材</strong></li></ul><p>当你把素材拖到地图上的那一刻，素材会被：</p><ul><li><strong>实例化</strong>为一个物体</li></ul><p>实例化之后：</p><ul><li>地图中的这个物体会拥有当时那一刻的属性快照</li><li>之后它与素材本体不再自动同步</li></ul><p>这是理解创游编辑器行为最关键的一条规则之一。</p><h2 id="_2-为什么修改素材后-地图里没变化" tabindex="-1">2. 为什么修改素材后，地图里没变化 <a class="header-anchor" href="#_2-为什么修改素材后-地图里没变化" aria-label="Permalink to “2. 为什么修改素材后，地图里没变化”">​</a></h2><p>因为：</p><ul><li>你修改的是素材栏中的模板</li><li>地图中的对象已经是独立实例</li></ul><p>也就是说：</p><ul><li><strong>素材更像模板</strong></li><li><strong>地图中的物体更像模板生成出来的实例</strong></li></ul><p>模板变了，不代表已经生成出来的实例会立刻跟着变。</p><h2 id="_3-快照机制的意义" tabindex="-1">3. 快照机制的意义 <a class="header-anchor" href="#_3-快照机制的意义" aria-label="Permalink to “3. 快照机制的意义”">​</a></h2><p>这种设计虽然一开始容易让人困惑，但其实有明显好处：</p><h3 id="_3-1-保证地图中对象可独立修改" tabindex="-1">3.1 保证地图中对象可独立修改 <a class="header-anchor" href="#_3-1-保证地图中对象可独立修改" aria-label="Permalink to “3.1 保证地图中对象可独立修改”">​</a></h3><p>如果实例永远强绑定模板，那么地图里单独调一个物体的参数会非常麻烦。</p><h3 id="_3-2-允许-局部特化" tabindex="-1">3.2 允许“局部特化” <a class="header-anchor" href="#_3-2-允许-局部特化" aria-label="Permalink to “3.2 允许“局部特化””">​</a></h3><p>你可以：</p><ul><li>先用同一个素材摆出多个物体</li><li>再单独修改其中某几个</li><li>不影响其他同素材生成的物体</li></ul><h3 id="_3-3-更接近常见游戏编辑器中的-预制体-实例-思路" tabindex="-1">3.3 更接近常见游戏编辑器中的“预制体/实例”思路 <a class="header-anchor" href="#_3-3-更接近常见游戏编辑器中的-预制体-实例-思路" aria-label="Permalink to “3.3 更接近常见游戏编辑器中的“预制体/实例”思路”">​</a></h3><p>虽然创游的术语叫“素材”，但行为上很接近：</p><ul><li>素材 = 模板/源定义</li><li>物体 = 地图中的实例对象</li></ul><h2 id="_4-怎样把地图中的修改反推回素材" tabindex="-1">4. 怎样把地图中的修改反推回素材 <a class="header-anchor" href="#_4-怎样把地图中的修改反推回素材" aria-label="Permalink to “4. 怎样把地图中的修改反推回素材”">​</a></h2><p>教程截图给出一个关键入口：</p><ul><li><strong>应用到原素材</strong></li></ul><p>这意味着：</p><ul><li>如果你在地图中选中了一个已经修改过的物体</li><li>并希望把它当前的属性状态反写回素材模板</li><li>可以通过“应用到原素材”来完成</li></ul><p>于是形成两种方向：</p><h3 id="方向-a-素材-地图" tabindex="-1">方向 A：素材 -&gt; 地图 <a class="header-anchor" href="#方向-a-素材-地图" aria-label="Permalink to “方向 A：素材 -&gt; 地图”">​</a></h3><p>重新摆放素材，生成新实例</p><h3 id="方向-b-地图-素材" tabindex="-1">方向 B：地图 -&gt; 素材 <a class="header-anchor" href="#方向-b-地图-素材" aria-label="Permalink to “方向 B：地图 -&gt; 素材”">​</a></h3><p>选中实例，使用“应用到原素材”把改动回写</p><h2 id="_5-编辑流程建议" tabindex="-1">5. 编辑流程建议 <a class="header-anchor" href="#_5-编辑流程建议" aria-label="Permalink to “5. 编辑流程建议”">​</a></h2><h3 id="场景-1-你刚发现模板属性写错了" tabindex="-1">场景 1：你刚发现模板属性写错了 <a class="header-anchor" href="#场景-1-你刚发现模板属性写错了" aria-label="Permalink to “场景 1：你刚发现模板属性写错了”">​</a></h3><p>如果地图里已经放了很多旧实例：</p><ul><li>单改素材本身通常不够</li><li>旧实例不一定自动更新</li></ul><p>你需要考虑：</p><ul><li>重新摆放</li><li>或者批量替换</li><li>或通过统一组件/统一脚本减少重复配置</li></ul><h3 id="场景-2-你只想改地图里某一个对象" tabindex="-1">场景 2：你只想改地图里某一个对象 <a class="header-anchor" href="#场景-2-你只想改地图里某一个对象" aria-label="Permalink to “场景 2：你只想改地图里某一个对象”">​</a></h3><p>直接改地图中的物体更合适，因为它本来就是独立实例。</p><h3 id="场景-3-你想让多个对象长期共享一套逻辑" tabindex="-1">场景 3：你想让多个对象长期共享一套逻辑 <a class="header-anchor" href="#场景-3-你想让多个对象长期共享一套逻辑" aria-label="Permalink to “场景 3：你想让多个对象长期共享一套逻辑”">​</a></h3><p>更推荐：</p><ul><li>用自定义组件</li><li>用公共脚本逻辑</li><li>用统一素材模板 + 少量实例修正</li></ul><h2 id="_6-自定义组件为什么能缓解这个问题" tabindex="-1">6. 自定义组件为什么能缓解这个问题 <a class="header-anchor" href="#_6-自定义组件为什么能缓解这个问题" aria-label="Permalink to “6. 自定义组件为什么能缓解这个问题”">​</a></h2><p>教程评论区里也出现了“自定义组件可以解决”的说法，这种理解有一定道理。</p><p>原因是：</p><ul><li>自定义组件可以把功能逻辑抽出来</li><li>相比手动改很多实例，自定义组件更适合统一挂载和复用</li><li>当需求主要是“行为一致”，而不是“每个实例外观完全一致”时，组件比反复改实例更稳定</li></ul><h2 id="_7-与素材系统教程的互证" tabindex="-1">7. 与素材系统教程的互证 <a class="header-anchor" href="#_7-与素材系统教程的互证" aria-label="Permalink to “7. 与素材系统教程的互证”">​</a></h2><p>结合其他教程页还能确认：</p><ul><li>素材是“贴图 + 各种组件”的组合体</li><li>不同类型素材可挂载的组件不同</li><li>素材库里可以复制、改类型、建文件夹管理</li></ul><p>这些内容进一步说明，创游的素材系统本质上承担两种职责：</p><ul><li>资源组织</li><li>功能模板</li></ul><p>而地图中的物体则承担：</p><ul><li>运行时场景实例</li><li>关卡内具体对象</li></ul><h2 id="_8-实战结论" tabindex="-1">8. 实战结论 <a class="header-anchor" href="#_8-实战结论" aria-label="Permalink to “8. 实战结论”">​</a></h2><p>可以把创游中的关系记成一句话：</p><blockquote><p>素材是模板，地图物体是实例；拖入地图时发生一次属性快照，之后默认各走各的。</p></blockquote><h2 id="_9-关键词" tabindex="-1">9. 关键词 <a class="header-anchor" href="#_9-关键词" aria-label="Permalink to “9. 关键词”">​</a></h2><ul><li>素材</li><li>物体</li><li>实例化</li><li>属性快照</li><li>应用到原素材</li><li>模板</li><li>实例</li><li>自定义组件</li></ul><h2 id="_10-来源" tabindex="-1">10. 来源 <a class="header-anchor" href="#_10-来源" aria-label="Permalink to “10. 来源”">​</a></h2><ul><li><code>资料/官方教程文档截图/Screenshot_20260418_120708.jpg</code></li><li><code>资料/官方教程文档截图/Screenshot_20260418_105946.jpg</code></li><li><code>资料/官方教程文档截图/Screenshot_20260418_110035.jpg</code></li><li>来源状态：历史来源路径；当前原图目录未列出可直接 OCR 的原图文件，正文依据已归档 OCR 与专题整理。</li></ul>',65)])])}const u=a(h,[["render",t]]);export{c as __pageData,u as default};
